param(
  [string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot),
  [string]$DefaultOutputPath=(Join-Path $ProjectRoot 'artifacts\s60\s60-default-first-screen-1938x1158.png'),
  [string]$WideOutputPath=(Join-Path $ProjectRoot 'artifacts\s60\s60-external-resources-1938x1158.png'),
  [string]$CompactOutputPath=(Join-Path $ProjectRoot 'artifacts\s60\s60-external-resources-1366x768.png')
)
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path,[int]$targetWidth,[int]$targetHeight){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();$dpiX=96*$targetWidth/[Math]::Max(1,$window.ActualWidth);$dpiY=96*$targetHeight/[Math]::Max(1,$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap($targetWidth,$targetHeight,$dpiX,$dpiY,[Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()};"${targetWidth}x${targetHeight} (WPF render)"}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s60-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$resourceType=$assembly.GetType('HalconWinFormsDemo.Models.VmExternalResourceData',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function Resource([string]$name,[string]$version,[string]$hash,[string]$health,[int]$refs){$r=[Activator]::CreateInstance($resourceType);$r.Name=$name;$r.SourcePath='D:\VisionResources\'+$name+'.dll';$r.ManagedRelativePath=$r.ResourceId+'\'+$hash+'.dll';$r.ManagedPath=(Join-Path $service.ResourceDirectory $r.ManagedRelativePath);$r.Sha256=$hash;$r.AssemblyVersion=$version;$r.DefaultTypeName='Factory.Vision.'+$name+'.Entry';$r.DefaultMethodName='Execute';$r.HealthState=$health;$r.HealthDetail=if($health-eq'Healthy'){'受管副本、哈希和入口签名均有效。'}else{'原始来源已变化；当前继续执行受管副本。'};$r.ReferenceCount=$refs;$r}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
try{
  $window.Topmost=$true;$window.Show();$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;Pump 550
  Assert((F 'ExternalResourceWorkspace').Visibility.ToString()-eq'Collapsed') 'Resource workspace is visible on default first screen';Assert((F 'DeveloperToolbarPanel').Children.Count-eq7) 'A permanent toolbar command was added';$default=Shot $DefaultOutputPath 1938 1158
  $resources=F 'externalResources';$resources.Add((Resource 'InspectionRules' '2.6.0.0' ('a'*64) 'Healthy' 3));$resources.Add((Resource 'ProductAdapter' '1.4.2.0' ('b'*64) 'UpdateAvailable' 1));$resources.Add((Resource 'StationFormatter' '3.1.0.0' ('c'*64) 'Healthy' 2));$main.GetMethod('OpenExternalResourcesButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;(F 'ExternalResourceListBox').SelectedIndex=0;Pump 550
  Assert((F 'ExternalResourceWorkspace').Visibility.ToString()-eq'Visible'-and(F 'MainWorkspaceGrid').Visibility.ToString()-eq'Collapsed') 'On-demand resource workspace is not active';Assert((F 'ExternalResourceListBox').ActualWidth-gt280-and(F 'ExternalResourceTypeNameTextBox').ActualWidth-gt200) 'Wide resource workbench did not lay out correctly';$wide=Shot $WideOutputPath 1938 1158
  $window.Width=1366;$window.Height=768;$window.Left=2;$window.Top=2;Pump 600;Assert((F 'ExternalResourceListBox').ActualHeight-gt250-and(F 'ExternalResourceManagedPathText').ActualWidth-gt200) 'Compact resource workbench is clipped';$compact=Shot $CompactOutputPath 1366 768
  Write-Output "S60_UI_CAPTURE=PASS; Default=$DefaultOutputPath; Wide=$WideOutputPath; Compact=$CompactOutputPath; DefaultSize=$default; WideSize=$wide; CompactSize=$compact; PermanentToolbarChildren=7; WorkspaceDefaultVisible=0; BSB=NOT_IMPLEMENTED_BY_USER_DIRECTIVE"
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
